function restoreStateC(w,src){if(!src)return;for(const x of src.formations||[]){const v=villageC(w,x.villageId),f=v&&formsC(v,w).find(q=>String(q.id)===String(x.formationId));if(!f)continue;f.v33cEngagementId=x.v33cEngagementId||null;f.v33cRegroupUntilCal=x.v33cRegroupUntilCal??null;f.v33cLastDefeatTile=x.v33cLastDefeatTile??null;f.v33cLastDefeatCal=x.v33cLastDefeatCal??null;f.v33cDefeatStreak=Number(x.v33cDefeatStreak||0);f.v33c1RetreatPath=Array.isArray(x.v33c1RetreatPath)?[...x.v33c1RetreatPath]:[];f.v33c1NextRetreatMoveCal=x.v33c1NextRetreatMoveCal??null;f.v33c1RegroupDays=x.v33c1RegroupDays??null;f.v33c1DisengageUntilCal=x.v33c1DisengageUntilCal??null;f.v33c1PostBattleUntilCal=x.v33c1PostBattleUntilCal??null;f.v33c1BattleMorale=Number(x.v33c1BattleMorale||0);f.v33c1MoraleLastCal=x.v33c1MoraleLastCal??null;f.v33c1MomentumUntilCal=x.v33c1MomentumUntilCal??null;f.v33c1MomentumFromTile=x.v33c1MomentumFromTile??null;f.v33c1NextMoveCal=x.v33c1NextMoveCal??null;f.v33c1LastMoveInfo=x.v33c1LastMoveInfo||null;f.v33c1LastStrategicTargetKind=x.v33c1LastStrategicTargetKind||null;}for(const x of src.garrisons||[]){const v=villageC(w,x.villageId),c=v?.military32A?.cohorts?.find(q=>String(q.id)===String(x.cohortId));if(c){c.v33cRoutedUntilCal=Number(x.routedUntilCal||0);c.v33c1BattleMorale=Number(x.v33c1BattleMorale||0);c.v33c1BaseMorale=Number((x.v33c1BaseMorale??c.morale)||0);c.v33c1MoraleLastCal=x.v33c1MoraleLastCal??null;}}}
