function escC(s){return String(s??'').replace(/[&<>\"']/g,c=>c==='&'?'&amp;':c==='<'?'&lt;':c==='>'?'&gt;':c==='\"'?'&quot;':'&#39;');}
function calLabelC(cal){if(!Number.isFinite(Number(cal)))return'-';const d=Math.max(0,Number(cal)-1),y=Math.floor(d/360)+1,r=d%360,q=Math.floor(r/90)+1,day=r%90+1;return`${y}년 ${q}분기 ${day}일`;}
function renderEngagementHistoryC(ui){const view=document.getElementById('view-stats');if(!view)return;let panel=document.getElementById('v33cEngagementHistoryPanel');if(!panel){panel=document.createElement('div');panel.id='v33cEngagementHistoryPanel';panel.className='panel';view.appendChild(panel);}const rows=engagementHistoryC(ui.world).slice(0,30);panel.innerHTML=`<div class="section-head"><div><h2>⚔ 지속 교전 기록</h2><div class="muted small">V0.33C에서 같은 전장의 연속 충돌을 하나의 Engagement로 묶어 기록합니다.</div></div><span class="tag">${engagementHistoryC(ui.world).length}건</span></div><div class="v33c-history">${rows.map(({war,e})=>{const a=villageC(ui.world,e.aId),b=villageC(ui.world,e.bId),win=villageC(ui.world,e.winnerId),dur=e.status==='ACTIVE'?Math.max(0,CALC(ui.world)-Number(e.startCal||CALC(ui.world))):Number(e.durationCalendarDays??Math.max(0,Number(e.endCal||e.startCal)-Number(e.startCal||0)));return`<div class="v33c-card ${e.status==='ACTIVE'?'active':''}"><b>${e.isCapital?'🏛️ ':''}${escC(a?.name||e.aId)} ↔ ${escC(b?.name||e.bId)}</b><span>${calLabelC(e.startCal)} · ${dur}일 · ${Number(e.rounds||0)}라운드 · ${e.status==='ACTIVE'?'교전 중':win?`${escC(win.name)} 승`:'종료'}</span><span class="muted">전장 #${Number(e.tileId)} · ${escC(e.endReason||e.source||'')}</span></div>`;}).join('')||'<div class="muted small">아직 V0.33C 지속 교전 기록이 없습니다.</div>'}</div>`;}
