const snapC=NS.Telemetry.prototype.snapshot;NS.Telemetry.prototype.snapshot=function(w,reason='AUTO',note=''){const s=snapC.call(this,w,reason,note);if(!s)return s;const ws=NS.V033.ensureWorld(w),active=activeEngC(w),reg=regroupRowsC(w).length;Object.assign(s.global,{activeEngagements33C:active,engagementsStarted33C:Number(ws.stats.engagementsStarted33C||0),engagementsEnded33C:Number(ws.stats.engagementsEnded33C||0),engagementRounds33C:Number(ws.stats.engagementRounds33C||0),capitalEngagements33C:Number(ws.stats.capitalEngagements33C||0),regroupingFormations33C:reg});for(const row of s.villages||[]){const v=villageC(w,row.id);if(!v)continue;row.engagedFormations33C=formsC(v,w).filter(f=>f.v33cEngagementId).length;row.regroupingFormations33C=formsC(v,w).filter(f=>CALC(w)<Number(f.v33cRegroupUntilCal??-99999)).length;}const ys=(this.yearlySummaries||[]).find(x=>Number(x.year)===Number(w.year));if(ys){Object.assign(ys.global,s.global);for(const n of ys.nations||[]){const row=s.villages.find(x=>Number(x.id)===Number(n.id));if(row){n.engagedFormations33C=row.engagedFormations33C;n.regroupingFormations33C=row.regroupingFormations33C;}}}return s;};
const csvC=NS.Telemetry.prototype.snapshotsCSV;NS.Telemetry.prototype.snapshotsCSV=function(){const base=csvC.call(this),lines=base.split('\n');if(!lines.length)return base;const G=['activeEngagements33C','engagementsStarted33C','engagementsEnded33C','engagementRounds33C','capitalEngagements33C','regroupingFormations33C'],R=['engagedFormations33C','regroupingFormations33C'],q=v=>`"${String(v??'').replace(/"/g,'""')}"`;lines[0]+=','+[...G,...R].map(q).join(',');let i=1;for(const s of this.snapshots||[])for(const row of s.villages||[]){if(i>=lines.length)break;lines[i++]+=','+[...G.map(k=>s.global?.[k]),...R.map(k=>row?.[k])].map(q).join(',');}return lines.join('\n');};
const jsonC=NS.Telemetry.prototype.toJSON;NS.Telemetry.prototype.toJSON=function(w){const d=jsonC.call(this,w);d.version='0.33C';Object.assign(d.worldSummary,{v33CRevision:REV33C,engagement33C:'same-tile hostile contact becomes a persistent Engagement with 3-5 day combat rounds instead of daily CONTACT_SWEEP battles',tacticalTempo33C:'field defeat triggers 15-30 day regroup; recent repeatedly lost routes receive temporary target-score penalties',capitalDefense33C:'core defenders require one additional consecutive round loss before breaking; routed garrison temporarily leaves combat and later recovers',warBalanceScope33C:'power, casualty, occupation, war exhaustion and declaration formulas remain V0.33/B1'});return d;};
const serC=NS.World.prototype.serialize,fromC=NS.World.from;NS.World.prototype.serialize=function(){const d=serC.call(this);d.version='0.33C';d.v33c={revision:REV33C,state:saveStateC(this),persistentEngagements:true,regroup:true,routeMemory:true};return d;};NS.World.from=function(d){if(d?.version==='0.33C'){const w=fromC({...d,version:'0.33B1'});return attachC(w,d);}return attachC(fromC(d),d);};
function dlC(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const savePrevC=NS.SaveSystem;(function(){const KEY='village-observer-v0-33c',fallback=['village-observer-v0-33b1','village-observer-v0-33b','village-observer-v0-33a','village-observer-v0-33','village-observer-v0-32f'];NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dlC(`village-observer-v033C-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){dlC(`village-observer-v033C-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){const text=w.telemetry.snapshotsCSV(),c=NS.V032E14?.validateCSV?.(text);if(c&&!c.ok)throw new Error(`CSV schema mismatch: expected ${c.columns} columns; bad rows ${c.bad.slice(0,8).join(', ')}`);dlC(`village-observer-v033C-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+text,'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attachC(await savePrevC.importMap(file));},async importScenario(file){return attachC(await savePrevC.importScenario(file));},exportScenario(w,meta=null){const x=NS.V032E14?.scenarioWrapper?.(w,meta);if(!x)return savePrevC.exportScenario(w,meta);x.meta={...x.meta,intendedVersion:'0.33C'};x.world.testScenario={...x.meta};if(x.world.v32e11)x.world.v32e11.scenario={...x.meta};dlC(`village-observer-v033C-scenario-${x.meta.id}.json`,JSON.stringify(x));return x;}};})();
if(NS.UI){const setC=NS.UI.prototype.setWorld,headC=NS.UI.prototype.renderHeader,tileC=NS.UI.prototype.renderTile,renderC=NS.UI.prototype.render;NS.UI.prototype.setWorld=function(w){return setC.call(this,attachC(w));};NS.UI.prototype.renderHeader=function(){headC.call(this);document.title='Village Observer V0.33C';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.33C</strong>';const st=this.q?.('runtimeStatus');if(st)st.textContent=`✓ V0.33C 지속 교전 · active wars ${NS.V033?.activeWars?.(this.world)?.length||0} · 교전 ${activeEngC(this.world)} · 재정비 ${regroupRowsC(this.world).length}`;augmentWarBannerC(this);};NS.UI.prototype.renderTile=function(){const r=tileC.call(this);augmentTileC(this);return r;};NS.UI.prototype.render=function(){const r=renderC.call(this);augmentWarBannerC(this);return r;};}
if(typeof document!=='undefined'){const st=document.createElement('style');st.textContent=`.v33c-banner-meta{margin-top:5px;font-size:11px;color:#ffd59c}.v33c-history{display:grid;gap:7px;max-height:48vh;overflow:auto}.v33c-card{display:grid;gap:3px;padding:8px 9px;border:1px solid rgba(130,155,185,.28);border-radius:9px;background:rgba(255,255,255,.025);font-size:11px}.v33c-card.active{border-color:rgba(255,170,80,.55);background:rgba(180,105,30,.08)}.v33c-tile{margin-top:7px;padding:7px 8px;border:1px solid rgba(255,180,80,.35);border-radius:8px;background:rgba(180,105,30,.07);font-size:11px}`;document.head.appendChild(st);}
if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.33C'))NS.PATCH_NOTES.unshift({version:'V0.33C',date:'2026-09-29',title:'Engagement + Tactical Tempo V1',summary:'B/B1 자연전쟁에서 같은 수도·전선 타일에 CONTACT_SWEEP 전투가 매일 반복되던 현상을 정식 지속 교전(Engagement)으로 승격합니다. 기존 전투력·사상자·점령·War Exhaustion 공식은 유지하고 전투 시간 구조와 패전 후 재정비만 다듬습니다.',sections:[['지속 교전',['적 Formation/수비대가 같은 타일에서 접촉하면 하나의 ENGAGEMENT_STARTED33C 상태를 생성합니다.','독립 전투를 매일 새로 만들지 않고 3~5 calendar-day 간격으로 교전 라운드를 수행합니다.','일반 전장은 3연속 라운드 패배 또는 최대 6라운드, 수도/핵심지 방어는 4연속 패배 또는 최대 7라운드에서 전선 붕괴를 판정합니다.']],['후퇴·재정비',['야전 Formation이 교전에서 붕괴하면 기존 후퇴를 수행한 뒤 15~30일 REGROUPING 상태에 들어갑니다.','재정비 중에는 재침공 이동을 하지 않으며 완료 후 전쟁 이동기로 복귀합니다.','최근 1년 내 같은 타일에서 반복 패배한 경로는 전략 목표 점수에 임시 페널티를 받아 대체 진입로가 존재하면 우회할 수 있습니다.']],['수도 수비',['CORE_GARRISON은 수도 Engagement에서 실제 수비 병력으로 계속 참가합니다.','수도 수비대가 붕괴하면 20~35일 ROUTED 상태로 전투에서 빠지고, 공격군은 실제 잔존 수비가 없을 때만 임시 점령합니다.']],['관측·저장',['Engagement 시작/라운드/종료, Formation 재정비, Garrison 붕괴 이벤트를 Devlog에 추가합니다.','Statistics에 지속 교전 기록을 추가하고 active engagement·라운드·수도 교전·재정비 수를 Snapshot/CSV에 기록합니다.','Formation regroup과 Garrison routed 상태는 V0.33C 전용 저장 상태로 보존합니다.']],['범위 유지',['전투력 계산식, Person 사상자 확률, 임시 점령 생산 65%, 점령 보급 페널티, 선전포고와 War Exhaustion/종전 공식은 변경하지 않습니다.','공성전·전쟁 목표·배상·영구 영토 할양·장비 밸런스는 후속 버전으로 미룹니다.']]]});
